<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
security_headers();student_private_headers();
$db=database();student_account_reconcile_confirmed_registrations($db);$student=student_account_current($db);
$id=(int)($_GET['id']??$_POST['id']??0);$view=(string)($_GET['view']??$_POST['view']??'exposure');if(!in_array($view,['exposure','process','review'],true))$view='exposure';
$next='/aluno/teste.php?id='.$id.'&view='.rawurlencode($view);if(!$student){header('Location: /aluno/login.php?next='.rawurlencode($next),true,303);exit;}$studentId=(int)$student['id'];$record=student_test_for_student($db,$id,$studentId);
if(!$record){http_response_code(404);student_shell_start('Registro não encontrado',null,$student);?><div class="student-empty">Registro não encontrado.</div><?php student_shell_end();exit;}
$error='';$contextScope=(string)($record['context_scope']??'course');
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('student-process-'.$id,$_POST['_csrf']??null))$error='Solicitação inválida.';
    else try{
        $action=(string)($_POST['action']??'');
        if($action==='save_exposure'){student_test_update_exposure($db,$id,$studentId,$_POST);$view='process';$_SESSION['student_process_notice']='Exposição salva.';}
        elseif($action==='add_step'){student_process_add_step($db,$id,$studentId,$_POST);$view='process';$_SESSION['student_process_notice']='Etapa adicionada.';}
        elseif($action==='delete_step'){student_process_delete_step($db,$id,(int)($_POST['step_id']??0),$studentId);$view='process';$_SESSION['student_process_notice']='Etapa removida.';}
        elseif($action==='save_result'){$notes=student_workspace_text($_POST['notes']??'',4000);$db->prepare('UPDATE student_tests SET notes=?,updated_at=? WHERE id=? AND student_id=?')->execute([$notes,utc_now(),$id,$studentId]);$view='review';$_SESSION['student_process_notice']='Resultado salvo.';}
        elseif($action==='upload'){$phase=(string)($_POST['phase']??'result');$file=$_FILES['image']??null;if(!is_array($file))throw new RuntimeException('Selecione uma imagem.');student_test_add_media_phase($db,$id,$studentId,$file,$phase);$view=$phase==='scene'?'exposure':'review';$_SESSION['student_process_notice']='Imagem adicionada.';}
        elseif($action==='delete_media'){student_test_delete_media($db,(int)($_POST['media_id']??0),$studentId);$view=(string)($_POST['phase']??'result')==='scene'?'exposure':'review';$_SESSION['student_process_notice']='Imagem removida.';}
        elseif($action==='submit'){if($contextScope!=='course')throw new RuntimeException('Registros pessoais não são enviados para avaliação.');student_test_submit($db,$id,$studentId);$view='review';$_SESSION['student_process_notice']='Registro enviado para avaliação.';}
        elseif($action==='message'){student_test_add_student_message($db,$id,$studentId,(string)($_POST['message']??''));$view='review';$_SESSION['student_process_notice']='Mensagem enviada.';}
        else throw new RuntimeException('Ação inválida.');
        header('Location: /aluno/teste.php?id='.$id.'&view='.$view,true,303);exit;
    }catch(Throwable $e){$error=$e->getMessage();}
}
$record=student_test_for_student($db,$id,$studentId)??$record;$steps=student_process_steps($db,$id);$nextChoices=student_process_next_choices($steps);$media=student_test_media($db,$id);$sceneMedia=student_test_media_by_phase($media,'scene');$resultMedia=student_test_media_by_phase($media,'result');$inventory=student_inventory_items($db,$studentId);$preparations=student_saved_preparations($db,$studentId);$messages=student_test_messages($db,$id);$notice=(string)($_SESSION['student_process_notice']??'');unset($_SESSION['student_process_notice']);$locked=(string)$record['status']==='reviewed';$developers=student_process_developer_catalog();
student_shell_start((string)$record['title'].' · Caderno',null,$student);?>
